<script setup lang="ts">
import { computed,onMounted,reactive,ref,watch } from "vue";
import { deleteExpense,listExpenses,saveExpense,type LocalExpense } from "@taher/db";
import type { ExpenseInput,ExpensePaymentMethod } from "@taher/core";
import { useAuthStore } from "../stores/auth.store";
const auth=useAuthStore();const companyId=computed(()=>auth.activeMembership?.company_id??"");
const canManage=computed(()=>auth.activeRole==="company_admin"||auth.activeRole==="manager");
const canCreate=computed(()=>canManage.value||auth.activeRole==="data_entry");
const canView=computed(()=>canManage.value||auth.activeRole==="accountant"||auth.activeRole==="data_entry");
const rows=ref<LocalExpense[]>([]);const loading=ref(false);const submitting=ref(false);
const error=ref("");const success=ref("");const open=ref(false);const editing=ref<string|null>(null);
const search=ref("");const method=ref<ExpensePaymentMethod|"all">("all");const from=ref("");const to=ref("");
const empty=():ExpenseInput=>({expense_date:new Date().toISOString().slice(0,10),expense_type:"مواد",supplier:null,invoice_number:null,amount_ht:0,tax_amount:0,payment_method:"cash",notes:null});
const form=reactive<ExpenseInput>(empty());
const total=computed(()=>rows.value.reduce((s,r)=>s+r.amount_ttc,0));
const fmt=(v:number)=>new Intl.NumberFormat("ar-DZ",{style:"currency",currency:auth.activeCompany?.currency_code||"DZD"}).format(v);
async function load(){if(!companyId.value||!canView.value){rows.value=[];return;}loading.value=true;error.value="";try{rows.value=await listExpenses(companyId.value,{search:search.value,paymentMethod:method.value,dateFrom:from.value||undefined,dateTo:to.value||undefined});}catch(e){error.value=e instanceof Error?e.message:"تعذر تحميل المصاريف.";}finally{loading.value=false;}}
function create(){editing.value=null;Object.assign(form,empty());open.value=true;error.value="";success.value="";}
function edit(r:LocalExpense){editing.value=r.id;Object.assign(form,{expense_date:r.expense_date,expense_type:r.expense_type,supplier:r.supplier,invoice_number:r.invoice_number,amount_ht:r.amount_ht,tax_amount:r.tax_amount,payment_method:r.payment_method,notes:r.notes});open.value=true;}
async function save(){if(!companyId.value||!canCreate.value||(editing.value!==null&&!canManage.value))return;submitting.value=true;error.value="";try{await saveExpense(companyId.value,{...form,amount_ht:Number(form.amount_ht),tax_amount:Number(form.tax_amount)},auth.user?.id??null,editing.value??undefined);open.value=false;success.value="تم حفظ المصروف محلياً وإضافته إلى الأرشيف.";await load();}catch(e){error.value=e instanceof Error?e.message:"تعذر حفظ المصروف.";}finally{submitting.value=false;}}
async function remove(r:LocalExpense){if(!canManage.value||!window.confirm("هل تريد حذف هذا المصروف؟"))return;try{await deleteExpense(companyId.value,r.id);success.value="تم حذف المصروف محلياً وتحديث الصندوق والأرشيف.";await load();}catch(e){error.value=e instanceof Error?e.message:"تعذر حذف المصروف.";}}
watch([search,method,from,to],()=>void load());onMounted(()=>void load());
</script>
<template>
<section class="space-y-6">
<header class="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p class="text-sm font-semibold text-brand-600">الحركة المالية</p><h1 class="mt-2 text-2xl font-bold text-slate-900">المصاريف والمشتريات</h1><p class="mt-1 text-sm text-slate-500">تسجيل المصاريف وحساب TVA وربط المدفوع نقداً بالصندوق وأرشفة مستنداتها.</p></div><button v-if="canCreate" class="primary-button" @click="create">＋ تسجيل مصروف</button></header>
<div v-if="!canView" class="panel p-5 text-sm text-amber-800">ليست لديك صلاحية الوصول إلى المصاريف.</div>
<div class="grid gap-4 sm:grid-cols-3"><article class="panel p-5"><p class="text-sm text-slate-500">عدد المصاريف</p><p class="mt-2 text-2xl font-bold">{{rows.length}}</p></article><article class="panel p-5"><p class="text-sm text-slate-500">إجمالي المصاريف TTC</p><p class="mt-2 text-2xl font-bold">{{fmt(total)}}</p></article><article class="panel p-5"><p class="text-sm text-slate-500">مدفوع نقداً</p><p class="mt-2 text-2xl font-bold">{{fmt(rows.filter(r=>r.payment_method==='cash').reduce((s,r)=>s+r.amount_ttc,0))}}</p></article></div>
<div class="panel overflow-hidden"><div class="grid gap-3 border-b border-slate-100 p-4 sm:grid-cols-2 xl:grid-cols-4"><input v-model="search" class="form-input" type="search" placeholder="بحث في التصنيف أو المورد أو الفاتورة"><select v-model="method" class="form-input"><option value="all">كل طرق الدفع</option><option value="cash">نقداً</option><option value="bank">تحويل بنكي</option><option value="credit">على الحساب</option></select><input v-model="from" class="form-input" type="date" aria-label="من تاريخ"><input v-model="to" class="form-input" type="date" aria-label="إلى تاريخ"></div>
<p v-if="error" role="alert" class="m-4 rounded-xl bg-red-50 p-3 text-sm text-red-700">{{error}}</p><p v-if="success" role="status" class="m-4 rounded-xl bg-emerald-50 p-3 text-sm text-emerald-700">{{success}}</p>
<div class="overflow-x-auto"><table class="w-full min-w-[900px] text-right text-sm"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th class="px-4 py-3">التاريخ</th><th class="px-4 py-3">التصنيف</th><th class="px-4 py-3">المورد</th><th class="px-4 py-3">HT</th><th class="px-4 py-3">TVA</th><th class="px-4 py-3">TTC</th><th class="px-4 py-3">الدفع</th><th class="px-4 py-3">الإجراءات</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="r in rows" :key="r.id"><td class="px-4 py-3">{{r.expense_date}}</td><td class="px-4 py-3 font-semibold">{{r.expense_type}}</td><td class="px-4 py-3">{{r.supplier||"—"}}</td><td class="px-4 py-3">{{fmt(r.amount_ht)}}</td><td class="px-4 py-3">{{fmt(r.tax_amount)}}</td><td class="px-4 py-3 font-bold">{{fmt(r.amount_ttc)}}</td><td class="px-4 py-3">{{r.payment_method==="cash"?"نقداً":r.payment_method==="bank"?"بنكي":"على الحساب"}}</td><td class="px-4 py-3"><div v-if="canManage" class="flex gap-2"><button class="secondary-button !px-3 !py-2" @click="edit(r)">تعديل</button><button class="rounded-lg border border-red-100 px-3 py-2 text-xs text-red-600" @click="remove(r)">حذف</button></div><span v-else class="text-xs text-slate-400">عرض فقط</span></td></tr><tr v-if="!loading&&!rows.length"><td colspan="8" class="px-4 py-12 text-center text-slate-400">لا توجد مصاريف مطابقة.</td></tr><tr v-if="loading"><td colspan="8" class="px-4 py-8 text-center text-slate-400">جارٍ التحميل...</td></tr></tbody></table></div></div>
<div v-if="open" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/50 p-4" @click.self="open=false"><section class="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white p-6 shadow-2xl"><h2 class="text-xl font-bold">{{editing?"تعديل مصروف":"تسجيل مصروف جديد"}}</h2><form class="mt-5 grid gap-4 sm:grid-cols-2" @submit.prevent="save">
<label class="form-field">التاريخ<input v-model="form.expense_date" class="form-input" type="date" required></label><label class="form-field">التصنيف<input v-model="form.expense_type" class="form-input" required maxlength="120"></label><label class="form-field">المورد<input v-model="form.supplier" class="form-input"></label><label class="form-field">رقم الفاتورة<input v-model="form.invoice_number" class="form-input"></label><label class="form-field">المبلغ HT<input v-model.number="form.amount_ht" class="form-input" type="number" min="0" step=".01" required></label><label class="form-field">TVA<input v-model.number="form.tax_amount" class="form-input" type="number" min="0" step=".01" required></label><label class="form-field">طريقة الدفع<select v-model="form.payment_method" class="form-input"><option value="cash">نقداً</option><option value="bank">تحويل بنكي</option><option value="credit">على الحساب</option></select></label><div class="rounded-xl bg-slate-50 p-3 text-sm"><span class="text-slate-500">الإجمالي TTC</span><strong class="mt-1 block text-lg">{{fmt(Number(form.amount_ht||0)+Number(form.tax_amount||0))}}</strong></div><label class="form-field sm:col-span-2">ملاحظات<textarea v-model="form.notes" class="form-input" rows="2"></textarea></label><div class="flex justify-end gap-3 sm:col-span-2"><button type="button" class="secondary-button" @click="open=false">إلغاء</button><button class="primary-button" type="submit" :disabled="submitting">{{submitting?"جارٍ الحفظ...":"حفظ المصروف"}}</button></div></form></section></div>
</section>
</template>
